package vn.rtr.aeris.control01;
import java.util.*;import java.util.concurrent.atomic.*;import vn.rtr.aeris.betaintegrated01.RunLifecycle;import vn.rtr.aeris.beta01runtime.Values;
/** Dedicated serial state observations. UI snapshots are not new physical MotionEvents. */
public final class InputScheduler {
 public interface Clock{long elapsedNs();long uptimeNs();long threadId();}
 public interface Serial{void execute(Runnable r);void later(Runnable r,long delayMs);void shutdown();}
 public interface Sink{void input(ControlAuthority.Input i);void action(String action,String id,String displayedHome,long originalClickNs);void invalid(String reason);void observation(Map<String,Object>event);}
 public static final long PERIOD_NS=50000000L,UI_MAX_NS=200000000L;
 public static final class Snapshot{
  public final long uiHeartbeatNs,touchRevision,lastMotionUptimeNs,releaseRevision,uiThreadId,viewEpoch,releaseFence;public final boolean foreground,focused,presented;public final int pointers,motionAction;private final double[]axes;
  public Snapshot(long hb,long revision,long motion,long release,long uiThread,long epoch,long fence,boolean fg,boolean focus,boolean presented,double[]axes,int pointers,int action){uiHeartbeatNs=hb;touchRevision=revision;lastMotionUptimeNs=motion;releaseRevision=release;uiThreadId=uiThread;viewEpoch=epoch;releaseFence=fence;foreground=fg;focused=focus;this.presented=presented;this.axes=axes.clone();this.pointers=pointers;motionAction=action;}
 }
 private final RunLifecycle.Context context;private final String source,provenance;private final long epoch;private final Clock clock;private final Serial serial;private final Sink sink;private final AtomicReference<Snapshot>current=new AtomicReference<>();private final AtomicInteger pending=new AtomicInteger();private final Object stateLock=new Object();private final AtomicLong cadence=new AtomicLong();private volatile boolean closed,active;private long sequence,consumedRelease,lastTick=-1,lastHeartbeat=-1,lastRevision=-1;
 public InputScheduler(RunLifecycle.Context c,String source,String provenance,long epoch,Clock clock,Serial serial,Sink sink){if(c==null||source==null||epoch<=0||clock==null||serial==null||sink==null)throw new IllegalArgumentException("SAMPLER_CONTEXT");context=c;this.source=source;this.provenance=provenance;this.epoch=epoch;this.clock=clock;this.serial=serial;this.sink=sink;}
 public void publishUI(Snapshot s){if(closed)return;if(s==null||s.viewEpoch!=epoch||s.uiHeartbeatNs<0||s.uiHeartbeatNs<lastHeartbeat||s.touchRevision<lastRevision||s.uiThreadId<=0||s.axes.length!=4){abort("UI_SNAPSHOT_CONTEXT_OR_CLOCK");return;}for(double a:s.axes)if(!Double.isFinite(a)||a< -1||a>1){abort("UI_SNAPSHOT_AXIS");return;}lastHeartbeat=s.uiHeartbeatNs;lastRevision=s.touchRevision;current.set(s);if(!s.foreground||!s.focused||!s.presented){if(active){abort("UI_LIVENESS_FOCUS_VIEW_CONTEXT_REVOKED");return;}invalidate(false);}}
 private Snapshot gate(){Snapshot s=current.get();long n=clock.elapsedNs();if(closed||s==null||s.viewEpoch!=epoch||!s.foreground||!s.focused||!s.presented||n<s.uiHeartbeatNs||n-s.uiHeartbeatNs>UI_MAX_NS||clock.threadId()==s.uiThreadId)throw new IllegalStateException("UI_LIVENESS_FOCUS_VIEW_CONTEXT_REQUIRED");return s;}
 private void emit(Snapshot s){long u=clock.uptimeNs(),n=clock.elapsedNs();if(n<s.uiHeartbeatNs||n-s.uiHeartbeatNs>UI_MAX_NS)throw new IllegalStateException("UI_LIVENESS_EXPIRED_BEFORE_SAMPLE");boolean release=s.releaseRevision>consumedRelease;if(release)consumedRelease=s.releaseRevision;Map<String,Object>o=Values.map("kind","IMMUTABLE_UI_TOUCH_STATE_SAMPLE_NOT_NEW_MOTION_EVENT","uiHeartbeatElapsedNs",s.uiHeartbeatNs,"touchRevision",s.touchRevision,"samplerThreadId",clock.threadId(),"uiThreadId",s.uiThreadId,"viewEpoch",s.viewEpoch,"releaseFence",s.releaseFence);sink.input(new ControlAuthority.Input(context,source,"ANDROID_UPTIME_NS_SAMPLER",provenance,++sequence,u,n,s.lastMotionUptimeNs,s.axes,s.pointers,s.motionAction,release,o));sink.observation(Values.map("sequence",sequence,"sampleElapsedNs",n,"uiHeartbeatElapsedNs",s.uiHeartbeatNs,"touchRevision",s.touchRevision,"threadId",clock.threadId(),"viewEpoch",s.viewEpoch));}
 private void enqueue(Runnable r){if(closed)return;if(pending.incrementAndGet()>128){pending.decrementAndGet();abort("SAMPLER_QUEUE_OVERFLOW");return;}try{serial.execute(()->{pending.decrementAndGet();if(!closed)r.run();});}catch(RuntimeException e){pending.decrementAndGet();abort("SAMPLER_EXECUTOR_REFUSED");}}
 private void abort(String why){if(closed)return;invalidate(true);sink.invalid(why);}
 private void tick(long token){if(closed||!active||token!=cadence.get())return;try{long now=clock.elapsedNs();if(lastTick>=0&&(now<lastTick||now-lastTick>UI_MAX_NS))throw new IllegalStateException("SAMPLER_TICK_LATE_NO_CATCHUP");Snapshot s=gate();emit(s);lastTick=now;serial.later(()->tick(token),50);}catch(Exception e){abort(e.getMessage());}}
 public void action(String action,String id,String home,long clickNs){final long requestedGeneration=cadence.get();enqueue(()->{try{if(closed||cadence.get()!=requestedGeneration)return;Snapshot s=gate();emit(s);if(closed||cadence.get()!=requestedGeneration)return;sink.action(action,id,home,clickNs);if("CONSENT".equals(action)){long token; synchronized(stateLock){if(closed||cadence.get()!=requestedGeneration)return;active=true;token=cadence.incrementAndGet();}lastTick=clock.elapsedNs();serial.later(()->tick(token),50);}}catch(Exception e){abort(e.getMessage());}});}
 public void release(){invalidate(false);enqueue(()->{try{emit(gate());}catch(Exception e){abort(e.getMessage());}});}
 public void stop(){invalidate(false);}
 public void close(){invalidate(true);serial.shutdown();}
 private void invalidate(boolean terminal){synchronized(stateLock){if(terminal)closed=true;active=false;cadence.incrementAndGet();}}
 public boolean active(){return active&&!closed;}
}
